#!/usr/bin/env python3
"""Regenerate docs/STATUS.md from verified tracked project state. No external APIs."""
import argparse
import json
from datetime import date
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
STATE = ROOT / "progress" / "project-state.json"
OUTPUT = ROOT / "docs" / "STATUS.md"
VALID = {"verified", "not_evidenced", "needs_review"}

def render(data):
    lines = [
        "# Project status",
        "",
        "> AUTO-GENERATED by `scripts/update_status.py` from `progress/project-state.json`. Do not edit manually.",
        "",
        f"Last human evidence review: **{data['reviewed_at']}**. This is **not** a Dutch proficiency score.",
        "",
        "A checked item means documented evidence exists, not that the learner has mastered a concept.",
        "",
    ]
    for p in data["phases"]:
        counts = {status: sum(t["status"] == status for t in p["tasks"]) for status in VALID}
        lines += [f"## {p['name']}", "",
            f"Verified: **{counts['verified']} / {len(p['tasks'])}** · Needs review: **{counts['needs_review']}** · Not evidenced: **{counts['not_evidenced']}**", ""]
        for t in p["tasks"]:
            if t["status"] not in VALID:
                raise ValueError(f"Invalid task status: {t['id']}: {t['status']}")
            mark = "x" if t["status"] == "verified" else " "
            evidence = f" — evidence: {t['evidence']}" if t.get("evidence") else ""
            lines.append(f"- [{mark}] **{t['id']}** {t['title']} ({t['status']}){evidence}")
        lines.append("")
    lines += ["## How to update this report", "",
              "1. Verify the underlying file, commit or workflow run.",
              "2. Propose a change to `progress/project-state.json` in a pull request.",
              "3. Run `python scripts/update_status.py` and check the diff.",
              "4. Let the scheduled GitHub Action regenerate documentation when the state changes.",
              "",
              "No automatic phase promotion or learner obligation is implied.", ""]
    return "\n".join(lines)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="Fail if generated document is stale")
    args = parser.parse_args()
    data = json.loads(STATE.read_text(encoding="utf-8"))
    ids = [t["id"] for p in data["phases"] for t in p["tasks"]]
    if len(ids) != len(set(ids)):
        raise ValueError("Duplicate task IDs")
    content = render(data)
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != content:
            raise SystemExit("docs/STATUS.md is stale; run python scripts/update_status.py")
        print("Project status matches tracked evidence.")
    else:
        OUTPUT.write_text(content, encoding="utf-8")
        print("Updated docs/STATUS.md")

if __name__ == "__main__":
    main()
